text:
.popup-panel-buttons-container {
  display: flex;
  align-items: center;
  margin: 0;
  justify-content: end;

  & > button {
    padding-inline: 15px;
    font-weight: 600;
    min-inline-size: 0;
    margin-inline: 8px 0;
    margin-block-end: 0;

    &:focus-visible {
      outline: var(--focus-outline);
      outline-offset: var(--focus-outline-offset);
    }

    &:not([disabled]):hover {
      background-color: var(--button-hover-background-color, color-mix(in srgb, currentColor 17%, transparent));
      color: var(--button-hover-text-color);

      &:active {
        background-color: var(--button-active-background-color, color-mix(in srgb, currentColor 30%, transparent));
      }
    }

    &.button-primary:not([disabled]) {
      color: var(--button-primary-text-color);
      background-color: var(--button-primary-background-color);

      &:hover {
        background-color: var(--button-primary-hover-background-color);
        border-color: var(--button-primary-border-color);
        box-shadow: var(--button-primary-hover-shadow);

        &:active {
          background-color: var(--button-primary-active-background-color);
          box-shadow: none;
        }
      }
    }
  }
}
